module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding for the sequence detector: 1101
    // State 0: Initial state / looking for first '1'
    // State 1: Found first '1'
    // State 2: Found '11'
    // State 3: Found '110'
    // State 4: Found '1101' (accepting state)
    typedef enum logic [2:0] {
        S0 = 3'b000,
        S1 = 3'b001,
        S2 = 3'b010,
        S3 = 3'b011,
        S4 = 3'b100
    } state_t;

    state_t state, next_state;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            S0: begin
                if (data == 1'b1)
                    next_state = S1;
                else
                    next_state = S0;
            end
            S1: begin
                if (data == 1'b1)
                    next_state = S2;
                else
                    next_state = S0; // reset on '0'
            end
            S2: begin
                if (data == 1'b0)
                    next_state = S3;
                else
                    next_state = S2; // stay on '1' (overlap possibility, though '11' then '1' stays in S2)
            end
            S3: begin
                if (data == 1'b1)
                    next_state = S4;
                else
                    next_state = S0; // reset on '0'
            end
            S4: begin
                // Once we have found the sequence, stay in S4 regardless of input
                next_state = S4;
            end
            default: next_state = S0;
        endcase
    end

    // State flip-flops (sequential, positive edge triggered)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    // Output logic
    // start_shifting is 1 once S4 is reached, and stays 1 forever until reset
    assign start_shifting = (state == S4);

endmodule

