                        done_reg   <= 1'b0;
                    end else begin
                        // Stay in IDLE, output and done remain unchanged
                    end
                end

                BYTE1: begin
                    // Store first byte
                    out_bytes_reg[23:16] <= in;
                    byte_cnt             <= 2;
                    state                <= BYTE2;
                    done_reg             <= 1'b0;
                end

                BYTE2: begin
                    // Store second byte
                    out_bytes_reg[15:8]  <= in;
                    byte_cnt             <= 3;
                    state                <= BYTE3;
                    done_reg             <= 1'b0;
                end

                BYTE3: begin
                    // Store third byte
                    out_bytes_reg[7:0]   <= in;
                    byte_cnt             <= 0;
                    state                <= IDLE;
                    done_reg             <= 1'b1;   // assert done in the cycle after 3rd byte
                end

                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end

    // Output assignment (combinational)
    // out_bytes is valid whenever done is asserted
    assign out_bytes = out_bytes_reg;
    assign done      = done_reg;

endmodule

