module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: BCD count value
);

    // Internal registers for the 4 BCD digits
    // q[3:0]   -> ones (d0)
    // q[7:4]   -> tens  (d1)
    // q[11:8]  -> hundreds (d2)
    // q[15:12] -> thousands (d3)
    reg  [3:0] d0, d1, d2, d3;

    // Wire for the enable outputs (active high when the digit can increment)
    wire ena_d0, ena_d1, ena_d2;

    // --- Ones digit (d0) ---
    // Always increments on every clock edge unless reset.
    // It rolls over from 9 to 0 and asserts ena_d0 to allow tens to increment.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            d0 <= 4'b0;
        end else begin
            if (d0 == 4'd9)
                d0 <= 4'b0;
            else
                d0 <= d0 + 1'b1;
        end
    end

    assign ena_d0 = (d0 == 4'd9); // Enable tens when ones rolls over

    // --- Tens digit (d1) ---
    // Increments only when ena_d0 is asserted (ones rolled over).
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            d1 <= 4'b0;
        end else begin
            if (ena_d0) begin
                if (d1 == 4'd9)
                    d1 <= 4'b0;
                else
                    d1 <= d1 + 1'b1;
            end
        end
    end

    assign ena_d1 = ena_d0 & (d1 == 4'd9); // Enable hundreds when tens rolls over

    // --- Hundreds digit (d2) ---
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            d2 <= 4'b0;
        end else begin
            if (ena_d1) begin
                if (d2 == 4'd9)
                    d2 <= 4'b0;
                else
                    d2 <= d2 + 1'b1;
            end
        end
    end

    assign ena_d2 = ena_d1 & (d2 == 4'd9); // Enable thousands when hundreds rolls over

    // --- Thousands digit (d3) ---
    // Increments only when ena_d2 is asserted.
    // For a 16-bit BCD counter, we simply allow it to roll over from 9 to 0.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            d3 <= 4'b0;
        end else begin
            if (ena_d2) begin
                if (d3 == 4'd9)
                    d3 <= 4'b0;
                else
                    d3 <= d3 + 1'b1;
            end
        end
    end

    // --- Output assignments ---
    // q[3:0]   = ones
    // q[7:4]   = tens
    // q[11:8]  = hundreds
    // q[15:12] = thousands
    assign q = {d3, d2, d1, d0};

    // ena[2] -> hundreds enable (ena_d2)
    // ena[1] -> tens enable    (ena_d1)
    // ena[0] -> ones enable    (ena_d0)
    assign ena = {ena_d2, ena_d1, ena_d0};

endmodule

