module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        WALK_LEFT_GND,      // 0: Walking left on ground
        WALK_RIGHT_GND,     // 1: Walking right on ground
        FALLING_LEFT,       // 2: Falling, was going left
        FALLING_RIGHT,      // 3: Falling, was going right
        DIGGING_LEFT,       // 4: Digging, going left
        DIGGING_RIGHT,      // 5: Digging, going right
        FALLEN_TOO_FAR,     // 6: Splattered (fallen >20 cycles)
        SPLATTERED          // 7: Splattered terminal state
    } state_type;

    state_type state, next_state;

    // Fall counter - counts clock cycles since ground went low
    logic [4:0] fall_counter, next_fall_counter;

    // Outputs: Moore machine
    assign walk_left   = (state == WALK_LEFT_GND);
    assign walk_right  = (state == WALK_RIGHT_GND);
    assign aaah        = (state == FALLING_LEFT) | (state == FALLING_RIGHT);
    assign digging     = (state == DIGGING_LEFT) | (state == DIGGING_RIGHT);

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT_GND;
            fall_counter <= 0;
        end else begin
            state <= next_state;
            fall_counter <= next_fall_counter;
        end
    end

    // Next-state and fall counter logic
    always_comb begin
        // Default values
        next_state = state;
        next_fall_counter = fall_counter;

        case (state)
            WALK_LEFT_GND: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Ground disappeared -> start falling
                    next_state = FALLING_LEFT;
                    next_fall_counter = 1; // Start counting
                end else if (dig) begin
                    // Start digging while walking left
                    next_state = DIGGING_LEFT;
                end else if (bump_right) begin
                    // Bumped on right -> walk right
                    next_state = WALK_RIGHT_GND;
                end else if (bump_left) begin
                    // Bumped on left -> walk left (already left, but spec says switch)
                    // Actually if bumped on left while walking left, do we switch?
                    // Spec: "if a Lemming is bumped on the left, it will walk right"
                    // Wait, that's the general rule. If already walking left and bumped on left...
                    // Let me re-read: "if a Lemming is bumped on the left (by receiving a 1 on bump_left), it will walk right."
                    // So bump_left always makes it walk right, regardless of current direction?
                    // That seems odd but that's what the spec says.
                    next_state = WALK_RIGHT_GND;
                end
                // If bumped on both sides at same time
                if (bump_left & bump_right) begin
                    // Spec: "If it's bumped on both sides at the same time, it will still switch directions."
                    // From current direction, switch to the opposite
                    // Since we're walking left, switch to right
                    next_state = WALK_RIGHT_GND;
                end
            end

            WALK_RIGHT_GND: begin
                if (!ground) begin
                    next_state = FALLING_RIGHT;
                    next_fall_counter = 1;
                end else if (dig) begin
                    next_state = DIGGING_RIGHT;
                end else if (bump_left) begin
                    next_state = WALK_LEFT_GND;
                end else if (bump_right) begin
                    next_state = WALK_RIGHT_GND;
                end
                if (bump_left & bump_right) begin
                    next_state = WALK_LEFT_GND;
                end
            end

            FALLING_LEFT: begin
                if (ground) begin
                    // Ground reappeared - check fall duration
                    if (fall_counter > 20) begin
                        // Fell too far -> splatter
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in same direction (left)
                        next_state = WALK_LEFT_GND;
                    end
                end else begin
                    // Still falling, increment counter
                    if (fall_counter < 31) // Max value
                        next_fall_counter = fall_counter + 1;
                    // Stay in FALLING_LEFT state
                end
            end

            FALLING_RIGHT: begin
                if (ground) begin
                    if (fall_counter > 20) begin
                        next_state = SPLATTERED;
                    end else begin
                        next_state = WALK_RIGHT_GND;
                    end
                end else begin
                    if (fall_counter < 31)
                        next_fall_counter = fall_counter + 1;
                end
            end

            DIGGING_LEFT: begin
                if (!ground) begin
                    // Reached other side, ground gone -> fall
                    next_state = FALLING_LEFT;
                    next_fall_counter = 1;
                end else if (!dig) begin
                    // Stop digging - resume walking in current direction (left)
                    next_state = WALK_LEFT_GND;
                end
                // else stay digging
            end

            DIGGING_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING_RIGHT;
                    next_fall_counter = 1;
                end else if (!dig) begin
                    next_state = WALK_RIGHT_GND;
                end
            end

            SPLATTERED: begin
                next_state = SPLATTERED;
                // fall_counter doesn't matter anymore
            end

            default: begin
                next_state = WALK_LEFT_GND;
            end
        endcase
    end

endmodule

