module TopModule(
    input clk,
    input reset,
    input [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    always @(posedge clk) begin
        if (reset) begin
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            // Default state: all outputs off (for flow logic)
            // Reset state as per spec: all outputs asserted (1'b1)
            // We will determine the actual state based on sensors

            // Determine nominal flow inputs based on sensor configuration
            // s[2] highest, s[1] middle, s[0] lowest

            // Case: Above s[2] -> s[0], s[1], s[2] asserted, Nominal: None
            if (s[2] && s[1] && s[0]) begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
            end
            // Case: Between s[2] and s[1] -> s[0], s[1] asserted, Nominal: fr0
            else if (s[2] && s[1]) begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
            // Case: Between s[1] and s[0] -> s[0] asserted, Nominal: fr0, fr1
            else if (s[1] && s[0]) begin
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
            // Case: Below s[0] -> None asserted, Nominal: fr0, fr1, fr2
            else begin
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b1;
            end
        end
    end

endmodule
